<template>
 <div class="info-backdrop patch-history-backdrop" @mousedown.self="$emit('close')" @keydown.stop @keyup.stop>
  <section ref="panel" class="patch-history" role="dialog" aria-modal="true" aria-labelledby="patch-history-title" tabindex="-1" @keydown.esc.prevent="$emit('close')" data-patch-history>
   <header><journal-icon name="progress"/><div><small>RIFTMON</small><h2 id="patch-history-title">{{ english?'Patch notes':'Notes de patch' }}</h2></div><button aria-label="Fermer" @click="$emit('close')">×</button></header>
   <div class="patch-history-scroll"><p v-if="loading" role="status">{{ english?'Opening the archive…':'Ouverture des archives…' }}</p><div v-else-if="error" role="alert"><p>{{ error }}</p><button @click="load">{{ english?'Retry':'Réessayer' }}</button></div><p v-else-if="!patches.length">{{ english?'No update in this archive yet.':'Aucune mise à jour dans ces archives pour le moment.' }}</p>
    <article v-for="(patch,index) in patches" :key="patch.version" class="patch-history-entry" :data-patch-version="patch.version"><div class="patch-date"><time :datetime="patch.date">{{ date(patch.date) }}</time><span v-if="index===0">{{ english?'Latest':'La plus récente' }}</span></div><h3>{{ copy(patch).title }}</h3><small class="patch-version">{{ patch.version }}</small><ul><li v-for="item in copy(patch).items" :key="item">{{ item }}</li></ul></article>
   </div>
   <footer>{{ english?'Public updates archived from 8 November 2026.':'Mises à jour publiques archivées depuis le 8 novembre 2026.' }}</footer>
  </section>
 </div>
</template>
<script>
import api from '@/services/api';
import JournalIcon from './JournalIcon.vue';
export default{components:{JournalIcon},props:{language:String},data:()=>({patches:[],loading:false,error:''}),computed:{english(){return this.language==='en';}},mounted(){this._active=true;this._previous=document.activeElement;this.$refs.panel.focus({preventScroll:true});this.load();this._trap=e=>{if(e.key!=='Tab')return;const a=[...this.$refs.panel.querySelectorAll('button:not(:disabled),[tabindex="0"]')],first=a[0],last=a.at(-1);if(e.shiftKey&&[first,this.$refs.panel].includes(document.activeElement)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}};this.$refs.panel.addEventListener('keydown',this._trap);},beforeDestroy(){this._active=false;this.$refs.panel?.removeEventListener('keydown',this._trap);if(this._previous?.isConnected)this._previous.focus({preventScroll:true});},methods:{
 async load(){if(this.loading)return;this.loading=true;this.error='';try{const{data}=await api.get('/patch-notes/history');if(this._active)this.patches=data.patches||[];}catch{if(this._active)this.error=this.english?'Could not open the archive. Please try again.':'Les archives sont momentanément indisponibles. Réessaie.';}finally{if(this._active)this.loading=false;}},
 copy(p){return p[this.english?'en':'fr']||p.fr;},date(d){return new Date(d+'T12:00:00Z').toLocaleDateString(this.english?'en-GB':'fr-FR',{day:'numeric',month:'long',year:'numeric'});}
}};
</script>
<style scoped>
.patch-history{display:flex;flex-direction:column;width:min(760px,100%);max-height:calc(100dvh - 30px);border:1px solid var(--journal-border);border-radius:14px;overflow:hidden;background:var(--journal-paper);color:var(--journal-ink);box-shadow:var(--journal-shadow);font:13px/1.6 var(--journal-font);text-align:left}.patch-history header{display:flex;align-items:center;gap:13px;flex:none;padding:19px 24px;border-bottom:1px solid var(--journal-border);background:var(--journal-soft)}header>.journal-icon{width:27px;height:30px;color:var(--journal-accent)}header>div{flex:1}header small{font-size:8px;letter-spacing:.15em;color:var(--journal-muted)}h2{font:25px Georgia,serif;color:var(--journal-heading);margin:2px 0 0}.patch-history button{font:inherit;color:inherit;border:1px solid var(--journal-border);background:var(--journal-card);border-radius:6px;min-height:40px;padding:6px 12px;cursor:pointer}.patch-history header>button{width:40px;border-radius:50%;font-size:24px;line-height:1}.patch-history button:focus-visible{outline:2px solid var(--journal-accent);outline-offset:3px}.patch-history-scroll{padding:20px 25px;min-height:120px;overflow:auto;overscroll-behavior:contain}.patch-history-entry{border-left:2px solid var(--journal-border);padding:0 0 20px 20px;margin-bottom:20px}.patch-history-entry:first-of-type{border-color:var(--journal-accent)}.patch-history-entry:last-child{margin-bottom:0;padding-bottom:0}.patch-date{display:flex;align-items:center;gap:12px;font-size:11px;color:var(--journal-muted)}.patch-date>span{font-size:9px;border:1px solid var(--journal-border);border-radius:5px;padding:2px 6px;background:var(--journal-soft);color:var(--journal-accent)}h3{font:21px Georgia,serif;color:var(--journal-heading);margin:10px 0 4px}.patch-version{color:var(--journal-muted);font-size:9px;overflow-wrap:anywhere}.patch-history ul{padding-left:16px;margin:14px 0 0}.patch-history li{margin:8px 0;padding-left:3px}.patch-history li::marker{color:var(--journal-accent)}.patch-history footer{flex:none;padding:12px 24px;border-top:1px solid var(--journal-border);font-size:10px;color:var(--journal-muted);background:var(--journal-soft)}@media(max-width:500px){.patch-history{max-height:calc(100dvh - 16px);border-radius:10px}.patch-history header{padding:15px}.patch-history-scroll{padding:17px 15px}.patch-history-entry{padding-left:12px}.patch-history footer{padding:11px 15px}h2{font-size:23px}h3{font-size:19px}.patch-history li{font-size:12px}}
header,footer{flex:none}
</style>
